package problemsolving;

public class Enhanced_Forloop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int number[] = {1,2,3,4,5,6,7,8};
		for (int n:number)
		{
			System.out.println(n);
		}
		
		char ch[]= {'S','J','C','B'};
		for(char dh:ch)
		{
			System.out.println(dh);
		}
	}

}
